contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 addedValue, uint256 subtractedValue) public payable {
        require(spender != address(0));
        bool decReverted;
        uint256 before;
        c.approve(spender, 0);
        bool incOk = c.increaseAllowance(spender, addedValue);
        uint256 afterInc = c.allowance(address(this), spender);
        before = afterInc;
        if (subtractedValue <= before) {
            // top-level conditional call pattern: perform inside try to observe revert flag
            try c.decreaseAllowance(spender, subtractedValue) {
                decReverted = false;
            } catch {
                decReverted = true;
            }
            uint256 afterDec = c.allowance(address(this), spender);
            assert(incOk && afterInc == addedValue && !decReverted && afterDec == addedValue - subtractedValue);
        } else {
            try c.decreaseAllowance(spender, subtractedValue) {
                decReverted = false;
            } catch {
                decReverted = true;
            }
            uint256 afterDec = c.allowance(address(this), spender);
            assert(incOk && afterInc == addedValue && decReverted && afterDec == before);
        }
    }
    receive() external payable {}
}

