contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 base, uint256 cut, uint256 tooMuch) public {
        require(spender != address(0));
        require(cut <= base);
        require(tooMuch > base + cut);

        bool ok0 = c.approve(spender, base);
        require(ok0);

        // decreasing by more than the allowance must revert and leave it unchanged
        bool reverted;
        try c.decreaseAllowance(spender, tooMuch) { reverted = false; }
        catch { reverted = true; }

        // a valid decrease succeeds
        bool ok1 = c.decreaseAllowance(spender, cut);

        assert(
            reverted &&
            ok1 &&
            c.allowance(address(this), spender) == base - cut
        );
    }

    receive() external payable {}
}

