contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, uint256 newMinTxnAmount) public {
        require(newOwner != address(this), "need distinct new owner");

        // owner() must initially be this test contract (it deployed c and is msg.sender)
        address ownerBefore = c.owner();

        // privileged call while still owner succeeds
        c.setMinTxnAmount(newMinTxnAmount);
        uint256 minAfterSet = c.minTxnAmount();

        // transfer ownership away
        c.changeOwner(newOwner);
        address ownerAfter = c.owner();

        // previous owner must no longer be able to call onlyOwner functions
        bool reverted;
        try c.setMinTxnAmount(newMinTxnAmount + 1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            ownerBefore == address(this) &&
            ownerAfter == newOwner &&
            minAfterSet == newMinTxnAmount &&
            reverted &&
            c.owner() == newOwner
        );
    }

    receive() external payable {}
}

