        try c.transferFrom(from, to, amount) { revertedFrom = false; }
        catch { revertedFrom = true; }

        uint256 fromBalAfter = c.balanceOf(from);
        uint256 toBalAfter = c.balanceOf(to);
        uint256 supplyAfter = c.totalSupply();

        assert(
            revertedTransfer && revertedFrom && !okTransfer &&
            fromBalAfter == fromBalBefore &&
            toBalAfter == toBalBefore &&
            supplyAfter == supplyBefore &&
            c.allowance(address(this), to) == amount
        );
    }

    receive() external payable {}
}

